#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::string st;
    std::cin >> st;

    int maxLen = 0, bracketCount = 0;
    std::string sb, sb2;

    for (int i = 0; i < n; i++) {
        if (st[i] == '(') {
            sb += "_";
            i++;
            while (i < n && st[i] != ')') {
                sb2 += st[i];
                i++;
            }
            sb2 += "_";
        } else {
            sb += st[i];
        }
    }

    std::vector<std::string> segments;
    size_t start = 0, end;
    while ((end = sb.find('_', start)) != std::string::npos) {
        segments.push_back(sb.substr(start, end - start));
        start = end + 1;
    }
    if (start < sb.size()) {
        segments.push_back(sb.substr(start));
    }

    for (const auto& segment : segments) {
        maxLen = std::max(maxLen, (int)segment.length());
    }

    std::vector<std::string> brackets;
    start = 0;
    while ((end = sb2.find('_', start)) != std::string::npos) {
        std::string b = sb2.substr(start, end - start);
        if (!b.empty()) {
            bracketCount++;
        }
        start = end + 1;
    }
    // Check for last segment if not empty
    if (start < sb2.size()) {
        std::string b = sb2.substr(start);
        if (!b.empty()) {
            bracketCount++;
        }
    }

    std::cout << maxLen << " " << bracketCount << std::endl;
    return 0;
}
